# Thin wrapper around scripts/deploy.py -- generated by Datrix, do not edit manually.
#
# This script does no deployment work of its own. It exists so an operator can
# run the deployment from PowerShell without thinking about interpreters: it
# anchors the working directory at the project root, makes sure the project
# virtual environment exists, activates it, hands every argument straight to
# scripts/deploy.py, and deactivates afterward. All deployment logic --
# every provider call, every retry, every check -- lives in that one Python
# script, so the PowerShell and bash entrypoints cannot drift apart.
#
# NOTE: this file deliberately declares NO param() block. Without one, every
# argument (including switch-shaped ones such as -Force) lands in the
# automatic $args array verbatim and is forwarded to the Python script, which
# owns the actual command-line contract. A param() block here would have to
# restate that contract -- the exact duplication this wrapper exists to remove.
#
# $ErrorActionPreference is deliberately left at its default: a native
# command's benign stderr output must not become a terminating error. Failure
# is detected through explicit $LASTEXITCODE checks instead.

# The deployment script and this wrapper are siblings; every path the Python
# script uses is relative to the project root, so anchor there first. This
# makes '.\scripts\deploy.ps1' (from the project root) and '.\deploy.ps1'
# (from inside the scripts folder) behave identically.
$ProjectRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..')).Path
Set-Location -LiteralPath $ProjectRoot

$VenvDir = Join-Path $ProjectRoot '.venv'
# A venv created on Windows lays its scripts out under Scripts\, one created by
# PowerShell 7 on Linux/macOS under bin/. Probe both so this wrapper works on
# either host.
$ActivateCandidates = @(
    (Join-Path $VenvDir 'Scripts\Activate.ps1'),
    (Join-Path $VenvDir 'bin/Activate.ps1')
)

function Find-BootstrapPython {
    # Interpreter used ONLY to create the virtual environment on first run.
    # Once the venv exists, its own interpreter runs the deployment.
    foreach ($candidate in @('python', 'python3')) {
        if (-not (Get-Command $candidate -ErrorAction SilentlyContinue)) { continue }
        # Reject Windows' App Execution Alias stub (a zero-byte shim that opens
        # the Microsoft Store instead of running Python): it resolves as a
        # command but cannot create a venv, and its own error names the Store
        # rather than the real problem.
        & $candidate -c "import sys; sys.exit(0)" 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) { return $candidate }
    }
    return $null
}

$Activate = $ActivateCandidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
if (-not $Activate) {
    $BootstrapPython = Find-BootstrapPython
    if (-not $BootstrapPython) {
        Write-Error @"
No usable Python interpreter found on PATH ('python' or 'python3').
  Expected: Python 3.11 or newer, used to create the project virtual environment at .venv\.
  Fix: install Python 3.11+ and make sure 'python' resolves, then re-run this script.
"@
        exit 1
    }
    Write-Host "==> Creating the project virtual environment (.venv\)"
    & $BootstrapPython -m venv $VenvDir
    if ($LASTEXITCODE -ne 0) {
        Write-Error @"
Could not create the project virtual environment at '$VenvDir' (exit $LASTEXITCODE).
  Command: $BootstrapPython -m venv $VenvDir
  Fix: ensure the interpreter ships the 'venv' module and that '$ProjectRoot' is writable, then re-run.
"@
        exit 1
    }
    $Activate = $ActivateCandidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if (-not $Activate) {
        Write-Error @"
The virtual environment at '$VenvDir' was created but has no Activate.ps1 (looked for Scripts\Activate.ps1 and bin/Activate.ps1).
  Fix: delete '$VenvDir' and re-run this script to recreate it.
"@
        exit 1
    }
}

. $Activate
python (Join-Path $PSScriptRoot 'deploy.py') @args
$status = $LASTEXITCODE
deactivate
exit $status
